<script setup lang="ts">import {ref,onMounted} from 'vue';import {go} from '../router';import {scenarios} from '../stores/scenarios';import {datasets} from '../stores/datasets';import {specs} from '../stores/specs';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),dataset=ref('demo-dataset'),spec=ref('demo-spec'),n=ref(400),seed=ref(20261112),cost=ref(true);const {error,busy,act}=useTask();onMounted(()=>Promise.all([scenarios.load(),datasets.load(),specs.load()]));function submit(){act(async()=>{await scenarios.create({name:name.value,dataset_id:dataset.value,spec_id:spec.value,n_samples:n.value,seed:seed.value,perturb_cost:cost.value});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({scenario_id:id});go('/results?run='+r.id)})}</script><template><PageHeading index="03 / 试算情景" title="求解一次配方，再把同一比例放进波动里。" note="每原浆3个属性各占一个LHS潜在维度；成本扰动开启再加每原浆1维。零宽度属性仍固定，不截断越界样本。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in scenarios.items.value" :key="r.id" class="scenario-row"><p class="eyebrow">FIXED FORMULA SCENARIO</p><h2>{{r.name}}</h2><dl><div><dt>LHS样本</dt><dd>{{r.n_samples}}</dd></div><div><dt>成本波动</dt><dd>{{r.perturb_cost?'开启':'关闭'}}</dd></div><div><dt>随机种子</dt><dd class="seed-dd">{{r.seed}}</dd></div></dl><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">求配方并做固定试算 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>建立试算情景</h2><label>情景名称<input v-model="name" required minlength="2"></label><label>原浆批次<select v-model="dataset"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>质量窗口<select v-model="spec"><option v-for="r in specs.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><div class="form-pair"><label>样本数<input type="number" v-model.number="n" min="20" max="2000"></label><label>随机种子<input type="number" v-model.number="seed" min="0" max="2147483647"></label></div><label class="checkbox-label"><input type="checkbox" v-model="cost">成本也按各原浆±幅度独立均匀扰动</label><button :disabled="busy">保存试算情景</button></form></div></template>
